"""Build six concise bilingual static pages."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
SCHOLAR='https://scholar.google.com/citations?user=uld736gAAAAJ'
PROFILE='https://new.skoltech.ru/en/persons/ilya-chepkasov'
def t(ru,en,tag='span',cls=''):
    return f'<{tag} class="{cls}" data-ru="{e(ru,quote=True)}" data-en="{e(en,quote=True)}">{e(ru)}</{tag}>'
def link(url,ru,en,cls='text-link'):
    ext=' target="_blank" rel="noopener noreferrer"' if url.startswith('https:') else ''
    return f'<a class="{cls}" href="{e(url,quote=True)}"{ext}>{t(ru,en)} <span aria-hidden="true">↗</span></a>'
NAV=[('index.html','Главная','Home'),('research.html','Исследования','Research'),('publications.html','Публикации','Publications'),('activities.html','Деятельность','Activities'),('cv.html','Биография','Biography'),('contact.html','Контакты','Contact')]
def page(file,ru,en,body,home=False):
    nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+f'>{t(r,v)}</a>' for f,r,v in NAV)
    head=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Илья Чепкасов — старший научный сотрудник Сколтеха. Вычислительное материаловедение, нанокатализ и материалы для энергетики."><title>{ru} — Илья Чепкасов</title><link rel="icon" href="assets/images/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/css/styles.css"><script src="assets/js/publications-data.js" defer></script><script src="assets/js/main.js" defer></script></head><body data-title-ru="{ru} — Илья Чепкасов" data-title-en="{en} — Ilya Chepkasov" class="{'home' if home else 'inner'}"><a class="skip" href="#main">{t('К содержанию','Skip to content')}</a><header class="site-header"><div class="header-inner"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">IC<span>·</span></span><span class="brand-name">{t('Илья Чепкасов','Ilya Chepkasov')}</span></a><button id="menu-toggle" class="menu-toggle" aria-controls="nav" aria-expanded="false">{t('Меню','Menu')}</button><nav id="nav" aria-label="Навигация" data-aria-ru="Навигация" data-aria-en="Main navigation">{nav}</nav><div class="language" role="group" aria-label="Язык / Language"><button data-lang="ru" aria-pressed="true">RU</button><span>/</span><button data-lang="en" aria-pressed="false">EN</button></div></div></header>'''
    footer=f'''<footer><div class="container footer-inner"><span>© 2026 {t('Илья Чепкасов','Ilya Chepkasov')}</span><div class="footer-links">{link(SCHOLAR,'Google Scholar','Google Scholar')}{link('https://orcid.org/0000-0001-8376-2999','ORCID','ORCID')}<a href="mailto:I.Chepkasov@skoltech.ru">Email ↗</a></div></div></footer></body></html>'''
    (ROOT/file).write_text(head+f'<main id="main">{body}</main>'+footer,encoding='utf-8',newline='\n')
def heading(ru,en,extra=''):
    return f'<section class="page-head container">{t(ru,en,"h1")}{extra}</section>'
FIELDS=[
('Нанокатализ','Nanocatalysis','Биметаллические частицы и структуры ядро–оболочка; адсорбция и каталитические свойства.','Bimetallic and core–shell nanoparticles; adsorption and catalytic properties.','10.1016/j.mtener.2025.102130'),
('Материалы для аккумуляторов','Battery materials','Углеродные и органические аноды, твердотельные электролиты, ионная проводимость.','Carbon and organic anodes, solid-state electrolytes, ionic conductivity.','10.1016/j.pmatsci.2026.101713'),
('Двумерные материалы','Two-dimensional materials','Графен, MoS₂, гетероструктуры: устойчивость и электронные свойства.','Graphene, MoS₂ and heterostructures: stability and electronic properties.','10.1021/acs.jpcc.2c03749'),
('Термоэлектрики','Thermoelectrics','Влияние легирования и дефектов на механические свойства PbTe.','Effects of doping and defects on the mechanical properties of PbTe.','10.1039/d5ta00823a'),
('Атомистическое моделирование','Atomistic modeling','DFT, молекулярная динамика, предсказание структуры, потенциалы машинного обучения.','DFT, molecular dynamics, structure prediction, machine-learning interatomic potentials.','10.1039/d5ta00823a')]
AREA_IDS=['catalysis','batteries','2d','thermoelectrics','modeling']
chips=''.join(f'<a href="research.html?area={area}">{t(ru,en)}<span aria-hidden="true">↗</span></a>' for area,(ru,en,*_) in zip(AREA_IDS,FIELDS[:4]))
home=f'''<section class="hero container"><div class="hero-copy">{t('Вычислительное материаловедение','Computational materials science','p','eyebrow')}<h1>{t('Илья','Ilya')}<br>{t('Чепкасов','Chepkasov')}</h1><div class="hero-role">{t('Старший научный сотрудник · Сколтех','Senior Research Scientist · Skoltech','p')}{t('Кандидат физико-математических наук','PhD in condensed matter physics','p')}</div><div class="research-chips">{chips}</div><p class="hero-methods">DFT · MD · Machine Learning</p><div class="hero-actions">{link('publications.html','Публикации','Publications','button')}{link(SCHOLAR,'Google Scholar','Google Scholar')}</div></div><figure class="portrait"><img src="assets/images/portrait.jpg" alt="Илья Чепкасов" data-alt-ru="Илья Чепкасов" data-alt-en="Ilya Chepkasov" width="640" height="640" fetchpriority="high"></figure></section>'''
page('index.html','Главная','Home',home,True)
WORKS=[
('Pt/C','Pt/C','Азотированный углеродный носитель','Nitrogen-doped carbon support','Small · 2025','10.1002/smll.202510144','pt-carbon.jpg','Графическая аннотация работы о Pt/C','Graphical abstract of the Pt/C study'),
('Органические электроды','Organic electrodes','Полициклические ароматические углеводороды в металл-ионных аккумуляторах.','Polycyclic aromatic hydrocarbons in metal-ion batteries.','Progress in Materials Science · 2026','10.1016/j.pmatsci.2026.101713','battery-review.webp','Схема материалов для металл-ионных аккумуляторов из обзора','Metal-ion battery materials diagram from the review'),
('Монослой V₃S₄','V₃S₄ monolayer','Атомная структура и электронные свойства материала для газовых сенсоров.','Atomic structure and electronic properties of a gas-sensing material.','Nanomaterials · 2022','10.3390/nano12050774','v3s4-monolayer.jpg','Структура, фононы и зонная структура V₃S₄; рисунок 2','V₃S₄ structure, phonons and electronic bands; Figure 2'),
('Дефекты в PbTe','Defects in PbTe','Легирование, химическая связь и механические свойства.','Doping, chemical bonding and mechanical properties.','Journal of Materials Chemistry A · 2025','10.1039/d5ta00823a','pbte-defects.jpg','Дефекты и локализация электронов в PbTe; рисунок 1','Defects and electron localization in PbTe; Figure 1'),
('Моделирование PbTe','Simulating PbTe','DFT и потенциалы машинного обучения для расчета деформации.','DFT and machine-learning potentials for deformation simulations.','Journal of Materials Chemistry A · 2025','10.1039/d5ta00823a','pbte-simulation.png','Моделирование деформации PbTe; рисунок 6','PbTe deformation simulations; Figure 6')]
tabs=''.join(f'<button id="tab-{area}" role="tab" data-area="{area}" aria-controls="panel-{area}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}">{t(ru,en)}<span class="tab-arrow" aria-hidden="true">↗</span></button>' for i,(area,(ru,en,*_)) in enumerate(zip(AREA_IDS,FIELDS)))
panels=[]
catalog=json.loads((ROOT/'assets/data/publications.json').read_text(encoding='utf-8'))
for i,(area,field,work) in enumerate(zip(AREA_IDS,FIELDS,WORKS)):
    ru,en,dr,de,_=field
    wr,we,sr,se,journal,doi,img,ar,ae=work
    image_path='assets/images/'+img
