pub+=f'''<section class="container publications-content"><div class="publication-tools"><label class="search-label">{t('Поиск','Search')}<input id="search" type="search" placeholder="Название, автор, журнал или DOI" data-placeholder-ru="Название, автор, журнал или DOI" data-placeholder-en="Title, author, journal or DOI" autocomplete="off"></label><label>{t('Год','Year')}<select id="year"><option value="all" data-ru="Все годы" data-en="All years">Все годы</option></select></label><label>{t('Порядок','Sort by')}<select id="sort"><option value="new" data-ru="Сначала новые" data-en="Newest first">Сначала новые</option><option value="old" data-ru="Сначала ранние" data-en="Oldest first">Сначала ранние</option><option value="title" data-ru="По названию" data-en="Title A–Z">По названию</option><option value="type" data-ru="Сначала обзоры" data-en="Reviews first">Сначала обзоры</option></select></label></div><div class="publication-bar"><div class="type-tabs" role="group" aria-label="Тип публикации" data-aria-ru="Тип публикации" data-aria-en="Publication type"><button data-type="all" aria-pressed="true">{t('Все','All')}</button><button data-type="review" aria-pressed="false">{t('Обзоры','Reviews')}</button><button data-type="article" aria-pressed="false">{t('Статьи','Articles')}</button><button data-type="conference" aria-pressed="false">{t('Конференции','Proceedings')}</button></div><span id="result-count" role="status" aria-live="polite"></span><button id="reset" class="reset">{t('Сбросить','Reset')}</button></div><div id="publication-list"></div><div id="empty" class="empty" hidden>{t('Публикации не найдены.','No publications found.')}</div><noscript><p>Для поиска включите JavaScript. / Enable JavaScript to search.</p></noscript><p class="catalog-note">{t('Резюме и Crossref · Проверено 05.10.2026 · Без автосинхронизации со Scholar','CV and Crossref · Checked Oct 5, 2026 · No Scholar auto-sync')}</p></section>'''
page('publications.html','Публикации','Publications',pub)
TIMELINE=[('2020 —','Сколтех','Skoltech','В Сколтехе с августа 2020 года. Сейчас — старший научный сотрудник.','Joined in August 2020. Currently Senior Research Scientist.'),('2018–2019 · 2021','HZDR, Дрезден','HZDR, Dresden','Приглашенный исследователь; атомистическое моделирование.','Visiting researcher; atomistic simulations.'),('2019–2020','НИТУ МИСИС','NUST MISIS','Приглашенный исследователь лаборатории неорганических наноматериалов.','Visiting researcher, Inorganic Nanomaterials Laboratory.'),('2014–2020','ХГУ им. Н. Ф. Катанова','Katanov Khakas State University','Лаборатория нанофизики (2014–2018); преподавание физики (2014–2020).','Nanophysics Laboratory (2014–2018); teaching physics (2014–2020).'),('2013','Кандидат физико-математических наук','PhD in condensed matter physics','Диссертация: моделирование синтеза наночастиц меди из газовой фазы.','Thesis: simulations of copper nanoparticle synthesis from the gas phase.'),('2005–2010','Образование: физика','Education: physics','ХГУ им. Н. Ф. Катанова, Абакан.','Katanov Khakas State University, Abakan.')]
timeline=''.join(f'<article class="timeline-row"><span class="timeline-date">{date}</span><div>{t(ru,en,"h2")}{t(dr,de,"p")}</div></article>' for date,ru,en,dr,de in TIMELINE)
